        root.dataset.sidebar = state.sidebarVisible ? 'visible' : 'hidden';
        root.dataset.agent = state.agentVisible ? 'visible' : 'hidden';
        root.dataset.git = state.gitVisible ? 'visible' : 'hidden';
        root.dataset.zen = state.zenMode ? 'true' : 'false';
